/* CommerceForge Dev Docs — Shared Design System */

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #484f58;
  --accent-blue: #475F91;
  --accent-blue-light: #6a87b8;
  --accent-green: #3fb950;
  --accent-green-dim: #2ea043;
  --accent-cyan: #58a6ff;
  --accent-purple: #bc8cff;
  --accent-orange: #f0883e;
  --code-bg: #161b22;
  --code-border: #30363d;
  --nav-height: 60px;
  --sidebar-width: 260px;
  --content-max: 1200px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', ui-monospace, monospace;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.4);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.5);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.6);
  --transition: 200ms ease;
  --transition-slow: 350ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-cyan); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; }

/* ─── Typography ─── */
h1, h2, h3, h4, h5 { font-weight: 600; line-height: 1.25; letter-spacing: -0.02em; }
h1 { font-size: clamp(2rem, 4vw, 3rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2rem); }
h3 { font-size: 1.2rem; }
h4 { font-size: 1rem; }
p { color: var(--text-secondary); }

.gradient-text {
  background: linear-gradient(135deg, #e6edf3 0%, var(--accent-cyan) 50%, var(--accent-blue-light) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ─── Layout ─── */
.container { max-width: var(--content-max); margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }

/* ─── Navigation ─── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: rgba(13,17,23,0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
}

.nav-inner {
  max-width: var(--content-max);
  margin: 0 auto;
  padding: 0 24px;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 15px;
  color: var(--text-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.nav-logo-mark {
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, var(--accent-blue) 0%, var(--accent-cyan) 100%);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 800;
  color: white;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-link {
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  text-decoration: none;
}
.nav-link:hover { color: var(--text-primary); background: var(--bg-tertiary); text-decoration: none; }
.nav-link.active { color: var(--text-primary); }

.nav-spacer { flex: 1; }

.nav-actions { display: flex; align-items: center; gap: 8px; }

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  font-size: 13px;
  cursor: pointer;
  transition: border-color var(--transition);
  font-family: var(--font-sans);
}
.nav-search:hover { border-color: var(--accent-blue); color: var(--text-secondary); }

.nav-btn {
  padding: 6px 14px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  font-family: var(--font-sans);
}
.nav-btn:hover { background: var(--bg-secondary); border-color: var(--accent-blue); }

.nav-btn-primary {
  background: var(--accent-green);
  border-color: var(--accent-green);
  color: #0d1117;
}
.nav-btn-primary:hover { background: var(--accent-green-dim); border-color: var(--accent-green-dim); }

/* ─── Hero ─── */
.hero {
  padding: 96px 0 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(ellipse at center, rgba(71,95,145,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(71,95,145,0.15);
  border: 1px solid rgba(71,95,145,0.4);
  border-radius: 100px;
  font-size: 12px;
  font-weight: 500;
  color: var(--accent-blue-light);
  margin-bottom: 24px;
}

.hero-badge-dot {
  width: 6px;
  height: 6px;
  background: var(--accent-green);
  border-radius: 50%;
}

.hero h1 { margin-bottom: 20px; }

.hero-subtitle {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  border: 1px solid transparent;
  font-family: var(--font-sans);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
}
.btn-primary:hover { background: var(--accent-green-dim); border-color: var(--accent-green-dim); text-decoration: none; color: #0d1117; }

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-color);
}
.btn-secondary:hover { background: var(--bg-secondary); border-color: var(--accent-blue); text-decoration: none; color: var(--text-primary); }

.btn-ghost {
  background: transparent;
  color: var(--accent-cyan);
  border-color: transparent;
  padding-left: 0;
}
.btn-ghost:hover { color: var(--text-primary); text-decoration: none; }

/* ─── Section Headers ─── */
.section-header { text-align: center; margin-bottom: 56px; }
.section-header h2 { margin-bottom: 12px; }
.section-header p { font-size: 16px; max-width: 600px; margin: 0 auto; }

.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-green);
  margin-bottom: 12px;
}

/* ─── Cards ─── */
.card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.card:hover {
  border-color: var(--border-color);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-link {
  text-decoration: none;
  display: block;
}
.card-link:hover { text-decoration: none; }

/* ─── Grid ─── */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-auto { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; }

/* ─── Product Cards ─── */
.product-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 32px;
  position: relative;
  overflow: hidden;
  transition: all var(--transition-slow);
  text-decoration: none;
  display: flex;
  flex-direction: column;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  opacity: 0;
  transition: opacity var(--transition);
}
.product-card:hover { border-color: var(--border-color); box-shadow: var(--shadow-md); transform: translateY(-3px); text-decoration: none; }
.product-card:hover::before { opacity: 1; }

.product-card.apps::before { background: linear-gradient(90deg, var(--accent-cyan), var(--accent-blue)); }
.product-card.storefronts::before { background: linear-gradient(90deg, var(--accent-purple), var(--accent-blue)); }
.product-card.agents::before { background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan)); }

.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}
.apps .product-card-icon { background: rgba(88,166,255,0.12); }
.storefronts .product-card-icon { background: rgba(188,140,255,0.12); }
.agents .product-card-icon { background: rgba(63,185,80,0.12); }

.product-card h3 { color: var(--text-primary); margin-bottom: 10px; font-size: 1.15rem; }
.product-card p { color: var(--text-secondary); font-size: 14px; line-height: 1.6; flex: 1; margin-bottom: 20px; }

.product-card-cta {
  color: var(--accent-cyan);
  font-size: 14px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 6px;
}
.product-card:hover .product-card-cta { color: var(--text-primary); }

/* ─── CLI Accordion ─── */
.cli-section { padding: 80px 0; background: var(--bg-primary); }

.accordion-wrapper { display: flex; flex-direction: column; gap: 8px; }

.accordion-item {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion-item.open { border-color: var(--border-color); }

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 24px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 600;
  font-family: var(--font-sans);
  transition: background var(--transition);
}
.accordion-trigger:hover { background: var(--bg-tertiary); }

.accordion-icon {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  flex-shrink: 0;
  transition: transform var(--transition);
}
.accordion-item.open .accordion-icon { transform: rotate(90deg); color: var(--accent-cyan); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.accordion-item.open .accordion-body { max-height: 600px; }

.accordion-content { padding: 0 24px 24px; }

.cli-steps { list-style: none; display: flex; flex-direction: column; gap: 16px; }

.cli-step {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.cli-step-num {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  flex-shrink: 0;
  margin-top: 2px;
}

.cli-step-text { color: var(--text-secondary); font-size: 14px; padding-top: 2px; }

/* ─── Package Manager Tabs ─── */
.pkg-tabs {
  margin-top: 12px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.pkg-tab-list {
  display: flex;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
}

.pkg-tab {
  padding: 8px 16px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: var(--font-mono);
  transition: all var(--transition);
  margin-bottom: -1px;
}
.pkg-tab.active { color: var(--accent-cyan); border-bottom-color: var(--accent-cyan); }
.pkg-tab:hover:not(.active) { color: var(--text-primary); }

.pkg-panel { display: none; }
.pkg-panel.active { display: block; }

/* ─── Code Block ─── */
.code-block {
  background: var(--code-bg);
  border-radius: 0;
  padding: 16px 20px;
  position: relative;
  overflow-x: auto;
}

.code-block code {
  font-family: var(--font-mono);
  font-size: 13px;
  color: #e6edf3;
  white-space: pre;
  display: block;
}

.code-block .prompt { color: var(--text-muted); user-select: none; }
.code-block .cmd { color: var(--accent-green); }
.code-block .arg { color: var(--accent-cyan); }
.code-block .flag { color: var(--accent-orange); }

.code-copy {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 4px 10px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
  font-family: var(--font-sans);
  transition: all var(--transition);
  opacity: 0;
}
.code-block:hover .code-copy { opacity: 1; }
.code-copy:hover { color: var(--text-primary); border-color: var(--accent-blue); }

.init-block { margin-top: 4px; }
.init-block .code-block { border-top: 1px solid var(--border-color); }

/* ─── Feature Grid ─── */
.feature-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 16px; }

.feature-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 20px 22px;
  cursor: default;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--border-color); background: var(--bg-tertiary); }

.feature-card-icon {
  font-size: 18px;
  margin-bottom: 10px;
  display: block;
}

.feature-card h4 { color: var(--text-primary); margin-bottom: 6px; font-size: 14px; font-weight: 600; }
.feature-card p { font-size: 13px; line-height: 1.5; }

/* ─── Launch / CTA Section ─── */
.launch-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }

.launch-card {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, rgba(33,38,45,0.8) 100%);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: all var(--transition);
}
.launch-card:hover { border-color: var(--border-color); box-shadow: var(--shadow-md); }
.launch-card h3 { color: var(--text-primary); font-size: 1.2rem; }
.launch-card p { font-size: 14px; flex: 1; }

/* ─── Community ─── */
.community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

.community-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px 20px;
  text-align: center;
  text-decoration: none;
  transition: all var(--transition);
  display: block;
}
.community-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); box-shadow: var(--shadow-sm); text-decoration: none; }

.community-card-icon { font-size: 28px; margin-bottom: 12px; display: block; }
.community-card h4 { color: var(--text-primary); font-size: 14px; margin-bottom: 6px; }
.community-card p { font-size: 13px; }

/* ─── Footer ─── */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-subtle);
  padding: 56px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand { grid-column: 1; }
.footer-brand p { font-size: 13px; margin-top: 12px; color: var(--text-muted); max-width: 220px; }

.footer-col h5 {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.footer-links { display: flex; flex-direction: column; gap: 8px; }
.footer-links a {
  font-size: 13px;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.footer-bottom p { font-size: 12px; color: var(--text-muted); }
.footer-bottom a { font-size: 12px; color: var(--text-muted); }
.footer-bottom a:hover { color: var(--text-secondary); }

/* ─── Sidebar Layout ─── */
.page-with-sidebar {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-subtle);
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  padding: 24px 0;
  transition: width var(--transition-slow), padding var(--transition-slow);
  scrollbar-width: thin;
  scrollbar-color: var(--bg-tertiary) transparent;
}

.sidebar.collapsed {
  width: 48px;
  padding: 24px 0;
  overflow: hidden;
}

.sidebar-header {
  padding: 0 16px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 16px;
}

.sidebar-title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
}

.sidebar-collapse-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  padding: 4px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition), background var(--transition);
  flex-shrink: 0;
}
.sidebar-collapse-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.sidebar.collapsed .sidebar-title { opacity: 0; }
.sidebar.collapsed .sidebar-header { justify-content: center; padding: 0 0 16px; }

.sidebar-nav { display: flex; flex-direction: column; }

.sidebar-section { margin-bottom: 8px; }

.sidebar-section-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding: 4px 16px 8px;
  white-space: nowrap;
  overflow: hidden;
}
.sidebar.collapsed .sidebar-section-label { opacity: 0; }

.sidebar-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 16px;
  color: var(--text-secondary);
  font-size: 13px;
  text-decoration: none;
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
  overflow: hidden;
  border-left: 2px solid transparent;
}
.sidebar-link:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); text-decoration: none; }
.sidebar-link.active { color: var(--accent-cyan); border-left-color: var(--accent-cyan); background: rgba(88,166,255,0.06); }
.sidebar-link span { overflow: hidden; }
.sidebar.collapsed .sidebar-link span { display: none; }
.sidebar.collapsed .sidebar-link { padding: 7px 12px; justify-content: center; border-left: none; }

.sidebar-icon { font-size: 14px; flex-shrink: 0; }

.page-content {
  flex: 1;
  min-width: 0;
  padding: 48px;
  max-width: none;
}

.page-content-inner { max-width: 860px; }

/* ─── Divider ─── */
.divider { height: 1px; background: var(--border-subtle); margin: 48px 0; }

/* ─── Tag / Badge ─── */
.tag {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 500;
}
.tag-blue { background: rgba(71,95,145,0.2); color: var(--accent-blue-light); border: 1px solid rgba(71,95,145,0.3); }
.tag-green { background: rgba(63,185,80,0.15); color: var(--accent-green); border: 1px solid rgba(63,185,80,0.25); }
.tag-yellow { background: rgba(240,136,62,0.15); color: var(--accent-orange); border: 1px solid rgba(240,136,62,0.25); }
.tag-purple { background: rgba(188,140,255,0.15); color: var(--accent-purple); border: 1px solid rgba(188,140,255,0.25); }

/* ─── Protocol Diagram ─── */
.protocol-diagram {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
  position: relative;
}

.actor-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 24px;
}

.actor-icon-wrap {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  border: 1px solid var(--border-color);
}

.actor-label { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.actor-sublabel { font-size: 11px; color: var(--text-muted); text-align: center; }

.actor-connector {
  flex: 1;
  height: 2px;
  background: linear-gradient(90deg, var(--border-color), var(--accent-blue), var(--border-color));
  min-width: 40px;
  max-width: 80px;
  align-self: center;
  margin-top: -24px;
}

/* ─── Support Cards ─── */
.support-cat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }

.support-cat-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition);
}
.support-cat-card:hover { border-color: var(--border-color); }
.support-cat-card h4 { color: var(--text-primary); margin-bottom: 10px; }
.support-cat-links { display: flex; flex-direction: column; gap: 6px; margin-top: 10px; }
.support-cat-links a { font-size: 13px; color: var(--accent-cyan); }

/* ─── Info Callout ─── */
.callout {
  padding: 16px 20px;
  border-radius: var(--radius-md);
  border-left: 3px solid;
  margin: 20px 0;
  font-size: 14px;
}
.callout-blue { background: rgba(71,95,145,0.1); border-color: var(--accent-blue); color: var(--text-secondary); }
.callout-yellow { background: rgba(240,136,62,0.08); border-color: var(--accent-orange); color: var(--text-secondary); }
.callout-green { background: rgba(63,185,80,0.08); border-color: var(--accent-green); color: var(--text-secondary); }

/* ─── Big CTA Block ─── */
.cta-block {
  background: linear-gradient(135deg, rgba(71,95,145,0.2) 0%, rgba(88,166,255,0.1) 100%);
  border: 1px solid rgba(71,95,145,0.3);
  border-radius: var(--radius-xl);
  padding: 56px 40px;
  text-align: center;
}
.cta-block h2 { margin-bottom: 16px; }
.cta-block p { margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .page-content { padding: 32px 24px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero { padding: 64px 0 56px; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .support-cat-grid { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .page-content { padding: 24px 16px; }
  .page-with-sidebar { flex-direction: column; }
  .section { padding: 56px 0; }
  .hero-actions { flex-direction: column; align-items: center; }
  .protocol-diagram { flex-direction: column; gap: 8px; }
  .actor-connector { width: 2px; height: 32px; min-width: unset; max-width: unset; align-self: center; background: linear-gradient(180deg, var(--border-color), var(--accent-blue), var(--border-color)); margin-top: 0; margin-left: -24px; }
}

@media (max-width: 480px) {
  .community-grid { grid-template-columns: 1fr; }
  .container { padding: 0 16px; }
}

/* ─── Utilities ─── */
.text-center { text-align: center; }
.mb-8 { margin-bottom: 8px; }
.mb-12 { margin-bottom: 12px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mb-48 { margin-bottom: 48px; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-32 { margin-top: 32px; }
.flex { display: flex; }
.flex-center { display: flex; align-items: center; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.hidden { display: none !important; }

/* scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--bg-tertiary); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--border-color); }

/* selection */
::selection { background: rgba(71,95,145,0.35); color: var(--text-primary); }

/* CommerceForge Dev Docs — Shared Design System */

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #484f58;
  --accent-blue: #475F91;
  --accent-blue-light: #6a87b8;
  --accent-green: #3fb950;
  --accent-green-dim: #2ea043;
  --accent-cyan: #58a6ff;
  --accent-purple: #bc8cff;
  --accent-orange: #f0883e;
  --code-bg: #161b22;
  --code-border: #30363d;
  --nav-height: 60px;
  --sidebar-width: 260px;
  --content-max: 1200px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', ui-monospace, monospace;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.4);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.5);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.6);
  --transition: 200ms ease;
  --transition-slow: 350ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-cyan); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; }

/* ─── Typography ─── */
h1, h2, h3, h4, h5 { font-weight: 600; line-height: 1.25; letter-spacing: -0.02em; }
h1 { font-size: clamp(2rem, 4vw, 3rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2rem); }
h3 { font-size: 1.2rem; }
h4 { font-size: 1rem; }
p { color: var(--text-secondary); }

.gradient-text {
  background: linear-gradient(135deg, #e6edf3 0%, var(--accent-cyan) 50%, var(--accent-blue-light) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ─── Layout ─── */
.container { max-width: var(--content-max); margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }

/* ─── Navigation ─── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: rgba(13,17,23,0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
}

.nav-inner {
  max-width: var(--content-max);
  margin: 0 auto;
  padding: 0 24px;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 15px;
  color: var(--text-primary);
  text-decoration: none;
  flex-shrink: 0;
}

.nav-logo-mark {
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, var(--accent-blue) 0%, var(--accent-cyan) 100%);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 800;
  color: white;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-link {
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  text-decoration: none;
}
.nav-link:hover { color: var(--text-primary); background: var(--bg-tertiary); text-decoration: none; }
.nav-link.active { color: var(--text-primary); }

.nav-spacer { flex: 1; }

.nav-actions { display: flex; align-items: center; gap: 8px; }

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  font-size: 13px;
  cursor: pointer;
  transition: border-color var(--transition);
  font-family: var(--font-sans);
}
.nav-search:hover { border-color: var(--accent-blue); color: var(--text-secondary); }

.nav-btn {
  padding: 6px 14px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  font-family: var(--font-sans);
}
.nav-btn:hover { background: var(--bg-secondary); border-color: var(--accent-blue); }

.nav-btn-primary {
  background: var(--accent-green);
  border-color: var(--accent-green);
  color: #0d1117;
}
.nav-btn-primary:hover { background: var(--accent-green-dim); border-color: var(--accent-green-dim); }

/* ─── Hero ─── */
.hero {
  padding: 96px 0 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(ellipse at center, rgba(71,95,145,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: rgba(71,95,145,0.15);
  border: 1px solid rgba(71,95,145,0.4);
  border-radius: 100px;
  font-size: 12px;
  font-weight: 500;
  color: var(--accent-blue-light);
  margin-bottom: 24px;
}

.hero-badge-dot {
  width: 6px;
  height: 6px;
  background: var(--accent-green);
  border-radius: 50%;
}

.hero h1 { margin-bottom: 20px; }

.hero-subtitle {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
  border: 1px solid transparent;
  font-family: var(--font-sans);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
}
.btn-primary:hover { background: var(--accent-green-dim); border-color: var(--accent-green-dim); text-decoration: none; color: #0d1117; }

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-color);
}
.btn-secondary:hover { background: var(--bg-secondary); border-color: var(--accent-blue); text-decoration: none; color: var(--text-primary); }

.btn-ghost {
  background: transparent;
  color: var(--accent-cyan);
  border-color: transparent;
  padding-left: 0;
}
.btn-ghost:hover { color: var(--text-primary); text-decoration: none; }

/* ─── Section Headers ─── */
.section-header { text-align: center; margin-bottom: 56px; }
.section-header h2 { margin-bottom: 12px; }
.section-header p { font-size: 16px; max-width: 600px; margin: 0 auto; }

.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-green);
  margin-bottom: 12px;
}

/* ─── Cards ─── */
.card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.card:hover {
  border-color: var(--border-color);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-link {
  text-decoration: none;
  display: block;
}
.card-link:hover { text-decoration: none; }

/* ─── Grid ─── */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-auto { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; }

/* ─── Product Cards ─── */
.product-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 32px;
  position: relative;
  overflow: hidden;
  transition: all var(--transition-slow);
  text-decoration: none;
  display: flex;
  flex-direction: column;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  opacity: 0;
  transition: opacity var(--transition);
}
.product-card:hover { border-color: var(--border-color); box-shadow: var(--shadow-md); transform: translateY(-3px); text-decoration: none; }
.product-card:hover::before { opacity: 1; }

.product-card.apps::before { background: linear-gradient(90deg, var(--accent-cyan), var(--accent-blue)); }
.product-card.storefronts::before { background: linear-gradient(90deg, var(--accent-purple), var(--accent-blue)); }
.product-card.agents::before { background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan)); }

.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-lg);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}
.apps .product-card-icon { background: rgba(88,166,255,0.12); }
.storefronts .product-card-icon { background: rgba(188,140,255,0.12); }
.agents .product-card-icon { background: rgba(63,185,80,0.12); }

.product-card h3 { color: var(--text-primary); margin-bottom: 10px; font-size: 1.15rem; }
.product-card p { color: var(--text-secondary); font-size: 14px; line-height: 1.6; flex: 1; margin-bottom: 20px; }

.product-card-cta {
  color: var(--accent-cyan);
  font-size: 14px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 6px;
}
.product-card:hover .product-card-cta { color: var(--text-primary); }

/* ─── CLI Accordion ─── */
.cli-section { padding: 80px 0; background: var(--bg-primary); }

.accordion-wrapper { display: flex; flex-direction: column; gap: 8px; }

.accordion-item {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion-item.open { border-color: var(--border-color); }

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 24px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 600;
  font-family: var(--font-sans);
  transition: background var(--transition);
}
.accordion-trigger:hover { background: var(--bg-tertiary); }

.accordion-icon {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  flex-shrink: 0;
  transition: transform var(--transition);
}
.accordion-item.open .accordion-icon { transform: rotate(90deg); color: var(--accent-cyan); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.accordion-item.open .accordion-body { max-height: 600px; }

.accordion-content { padding: 0 24px 24px; }

.cli-steps { list-style: none; display: flex; flex-direction: column; gap: 16px; }

.cli-step {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.cli-step-num {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  flex-shrink: 0;
  margin-top: 2px;
}

.cli-step-text { color: var(--text-secondary); font-size: 14px; padding-top: 2px; }

/* ─── Package Manager Tabs ─── */
.pkg-tabs {
  margin-top: 12px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.pkg-tab-list {
  display: flex;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
}

.pkg-tab {
  padding: 8px 16px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: var(--font-mono);
  transition: all var(--transition);
  margin-bottom: -1px;
}
.pkg-tab.active { color: var(--accent-cyan); border-bottom-color: var(--accent-cyan); }
.pkg-tab:hover:not(.active) { color: var(--text-primary); }

.pkg-panel { display: none; }
.pkg-panel.active { display: block; }

/* ─── Code Block ─── */
.code-block {
  background: var(--code-bg);
  border-radius: 0;
  padding: 16px 20px;
  position: relative;
  overflow-x: auto;
}

.code-block code {
  font-family: var(--font-mono);
  font-size: 13px;
  color: #e6edf3;
  white-space: pre;
  display: block;
}

.code-block .prompt { color: var(--text-muted); user-select: none; }
.code-block .cmd { color: var(--accent-green); }
.code-block .arg { color: var(--accent-cyan); }
.code-block .flag { color: var(--accent-orange); }

.code-copy {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 4px 10px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
  font-family: var(--font-sans);
  transition: all var(--transition);
  opacity: 0;
}
.code-block:hover .code-copy { opacity: 1; }
.code-copy:hover { color: var(--text-primary); border-color: var(--accent-blue); }

.init-block { margin-top: 4px; }
.init-block .code-block { border-top: 1px solid var(--border-color); }

/* ─── Feature Grid ─── */
.feature-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 16px; }

.feature-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 20px 22px;
  cursor: default;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--border-color); background: var(--bg-tertiary); }

.feature-card-icon {
  font-size: 18px;
  margin-bottom: 10px;
  display: block;
}

.feature-card h4 { color: var(--text-primary); margin-bottom: 6px; font-size: 14px; font-weight: 600; }
.feature-card p { font-size: 13px; line-height: 1.5; }

/* ─── Launch / CTA Section ─── */
.launch-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }

.launch-card {
  background: linear-gradient(135deg, var(--bg-secondary) 0%, rgba(33,38,45,0.8) 100%);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: all var(--transition);
}
.launch-card:hover { border-color: var(--border-color); box-shadow: var(--shadow-md); }
.launch-card h3 { color: var(--text-primary); font-size: 1.2rem; }
.launch-card p { font-size: 14px; flex: 1; }

/* ─── Community ─── */
.community-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

.community-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px 20px;
  text-align: center;
  text-decoration: none;
  transition: all var(--transition);
  display: block;
}
.community-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); box-shadow: var(--shadow-sm); text-decoration: none; }

.community-card-icon { font-size: 28px; margin-bottom: 12px; display: block; }
.community-card h4 { color: var(--text-primary); font-size: 14px; margin-bottom: 6px; }
.community-card p { font-size: 13px; }

/* ─── Footer ─── */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-subtle);
  padding: 56px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand { grid-column: 1; }
.footer-brand p { font-size: 13px; margin-top: 12px; color: var(--text-muted); max-width: 220px; }

.footer-col h5 {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.footer-links { display: flex; flex-direction: column; gap: 8px; }
.footer-links a {
  font-size: 13px;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.footer-bottom p { font-size: 12px; color: var(--text-muted); }
.footer-bottom a { font-size: 12px; color: var(--text-muted); }
.footer-bottom a:hover { color: var(--text-secondary); }

/* ─── Sidebar Layout ─── */
.page-with-sidebar {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-subtle);
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  padding: 24px 0;
  transition: width var(--transition-slow), padding var(--transition-slow);
  scrollbar-width: thin;
  scrollbar-color: var(--bg-tertiary) transparent;
}

.sidebar.collapsed {
  width: 48px;
  padding: 24px 0;
  overflow: hidden;
}

.sidebar-header {
  padding: 0 16px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 16px;
}

.sidebar-title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
}

.sidebar-collapse-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  padding: 4px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition), background var(--transition);
  flex-shrink: 0;
}
.sidebar-collapse-btn:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.sidebar.collapsed .sidebar-title { opacity: 0; }
.sidebar.collapsed .sidebar-header { justify-content: center; padding: 0 0 16px; }

.sidebar-nav { display: flex; flex-direction: column; }

.sidebar-section { margin-bottom: 8px; }

.sidebar-section-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding: 4px 16px 8px;
  white-space: nowrap;
  overflow: hidden;
}
.sidebar.collapsed .sidebar-section-label { opacity: 0; }

.sidebar-link {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 16px;
  color: var(--text-secondary);
  font-size: 13px;
  text-decoration: none;
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
  overflow: hidden;
  border-left: 2px solid transparent;
}
.sidebar-link:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); text-decoration: none; }
.sidebar-link.active { color: var(--accent-cyan); border-left-color: var(--accent-cyan); background: rgba(88,166,255,0.06); }
.sidebar-link span { overflow: hidden; }
.sidebar.collapsed .sidebar-link span { display: none; }
.sidebar.collapsed .sidebar-link { padding: 7px 12px; justify-content: center; border-left: none; }

.sidebar-icon { font-size: 14px; flex-shrink: 0; }

.page-content {
  flex: 1;
  min-width: 0;
  padding: 48px;
  max-width: none;
}

.page-content-inner { max-width: 860px; }

/* ─── Divider ─── */
.divider { height: 1px; background: var(--border-subtle); margin: 48px 0; }

/* ─── Tag / Badge ─── */
.tag {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 500;
}
.tag-blue { background: rgba(71,95,145,0.2); color: var(--accent-blue-light); border: 1px solid rgba(71,95,145,0.3); }
.tag-green { background: rgba(63,185,80,0.15); color: var(--accent-green); border: 1px solid rgba(63,185,80,0.25); }
.tag-yellow { background: rgba(240,136,62,0.15); color: var(--accent-orange); border: 1px solid rgba(240,136,62,0.25); }
.tag-purple { background: rgba(188,140,255,0.15); color: var(--accent-purple); border: 1px solid rgba(188,140,255,0.25); }

/* ─── Protocol Diagram ─── */
.protocol-diagram {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
  position: relative;
}

.actor-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 24px;
}

.actor-icon-wrap {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  border: 1px solid var(--border-color);
}

.actor-label { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.actor-sublabel { font-size: 11px; color: var(--text-muted); text-align: center; }

.actor-connector {
  flex: 1;
  height: 2px;
  background: linear-gradient(90deg, var(--border-color), var(--accent-blue), var(--border-color));
  min-width: 40px;
  max-width: 80px;
  align-self: center;
  margin-top: -24px;
}

/* ─── Support Cards ─── */
.support-cat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }

.support-cat-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition);
}
.support-cat-card:hover { border-color: var(--border-color); }
.support-cat-card h4 { color: var(--text-primary); margin-bottom: 10px; }
.support-cat-links { display: flex; flex-direction: column; gap: 6px; margin-top: 10px; }
.support-cat-links a { font-size: 13px; color: var(--accent-cyan); }

/* ─── Info Callout ─── */
.callout {
  padding: 16px 20px;
  border-radius: var(--radius-md);
  border-left: 3px solid;
  margin: 20px 0;
  font-size: 14px;
}
.callout-blue { background: rgba(71,95,145,0.1); border-color: var(--accent-blue); color: var(--text-secondary); }
.callout-yellow { background: rgba(240,136,62,0.08); border-color: var(--accent-orange); color: var(--text-secondary); }
.callout-green { background: rgba(63,185,80,0.08); border-color: var(--accent-green); color: var(--text-secondary); }

/* ─── Big CTA Block ─── */
.cta-block {
  background: linear-gradient(135deg, rgba(71,95,145,0.2) 0%, rgba(88,166,255,0.1) 100%);
  border: 1px solid rgba(71,95,145,0.3);
  border-radius: var(--radius-xl);
  padding: 56px 40px;
  text-align: center;
}
.cta-block h2 { margin-bottom: 16px; }
.cta-block p { margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .page-content { padding: 32px 24px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero { padding: 64px 0 56px; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .support-cat-grid { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .page-content { padding: 24px 16px; }
  .page-with-sidebar { flex-direction: column; }
  .section { padding: 56px 0; }
  .hero-actions { flex-direction: column; align-items: center; }
  .protocol-diagram { flex-direction: column; gap: 8px; }
  .actor-connector { width: 2px; height: 32px; min-width: unset; max-width: unset; align-self: center; background: linear-gradient(180deg, var(--border-color), var(--accent-blue), var(--border-color)); margin-top: 0; margin-left: -24px; }
}

@media (max-width: 480px) {
  .community-grid { grid-template-columns: 1fr; }
  .container { padding: 0 16px; }
}

/* ─── Utilities ─── */
.text-center { text-align: center; }
.mb-8 { margin-bottom: 8px; }
.mb-12 { margin-bottom: 12px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mb-48 { margin-bottom: 48px; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-32 { margin-top: 32px; }
.flex { display: flex; }
.flex-center { display: flex; align-items: center; }
.gap-8 { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.hidden { display: none !important; }

/* scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--bg-tertiary); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--border-color); }

/* selection */
::selection { background: rgba(71,95,145,0.35); color: var(--text-primary); }

